function formatDate(value) {
    if (!value) return "";
    // Firestore Timestamp
    if (value?.toDate) {
        return value.toDate().toLocaleDateString("en-GB");
    }
    // Normal date string
    try {
        return new Date(value).toLocaleDateString("en-GB");
    } catch  {
        return value;
    }
}
